<h1>Verification</h1><p>Attempts flagged for review are excluded from rankings until a reviewer decides.</p>
<section class="card"><h2>Pending review (<?= count($rows) ?>)</h2><?php if (!$rows): ?><p class="empty">Nothing is waiting for review.</p><?php else: ?><div class="table-wrap"><table class="cards-sm"><thead><tr><th>Participant</th><th>Quiz</th><th>Score</th><th>Left page</th><th>Reason flagged</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td data-l="Participant"><?= e($r['full_name']) ?></td><td data-l="Quiz"><?= e($r['title']) ?></td><td data-l="Score"><?= e(num($r['final_marks'])) ?>/<?= (int)$r['max_marks'] ?></td><td data-l="Left page"><?= (int)$r['lefts'] ?></td><td data-l="Reason"><?= e($r['eligibility_reason']) ?></td><td><a class="btn btn-sm" href="<?= e(url('/admin/submissions/' . $r['id'])) ?>">Review</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="card"><h2>Recent reviewer decisions</h2><?php if (!$recent): ?><p class="empty">No decisions yet.</p><?php endif; ?><ul class="plain"><?php foreach ($recent as $r): ?><li><?= badge($r['decision']) ?> <a href="<?= e(url('/admin/submissions/' . $r['aid'])) ?>"><?= e($r['participant']) ?> · <?= e($r['title']) ?></a> — <?= e($r['reason']) ?><small><?= e($r['reviewer'] ?? '') ?> · <?= e(fmt_dt($r['created_at'])) ?></small></li><?php endforeach; ?></ul></section>
